html:
{% set repair_items = [] %}
{% for row in doc.custom_rejected_item_table %}
    {% if not row.rejected_quantity %}
        {% set _ = repair_items.append(row) %}
    {% endif %}
{% endfor %}

{% set rejected_items = [] %}
{% for row in doc.custom_rejected_item_table %}
    {% if row.rejected_quantity %}
        {% set _ = rejected_items.append(row) %}
    {% endif %}
{% endfor %}

<div style="font-family: Arial, sans-serif; font-size: 10px; color: #000;">

<div id="header-html" class="visible-pdf">
    <table style="width: 100%; border-collapse: collapse; font-family: Arial, Helvetica, sans-serif; margin-top:-50px;">

        <!-- ROW 2: LOGO AND ADDRESS -->
        <tr>
            <!-- LEFT: Logo -->
            <td style="width: 33.33%; vertical-align: top; text-align: left; padding: 0;">
                {% set company_logo = frappe.db.get_value("Company", doc.company, "company_logo") %}
                
                {% if company_logo %}
                    <div style="height: 84px; overflow: hidden; position: relative; width: 100%;">
                        <img src="{{ company_logo }}" alt="{{ doc.company }}"
                             style="position: absolute; top: -18px; left: 0; height: 120px; width: auto;">
                    </div>
                {% endif %}
            </td>
            
            <td  style="width: 33.33%; text-align: center; font-size: 25px; font-weight: 400; color: #222; padding-bottom: 15px;">
                Rejection Invoice
            </td>
            <!-- RIGHT: Address -->
            <td style="width: 33.33%; vertical-align: top; text-align: right; font-size: 12px; line-height: 1.4; padding: 0;">
                
                {% set company_address = frappe.db.get_value(
                    "Address",
                    doc.company_address,
                    ["address_line1", "city", "state", "pincode"],
                    as_dict=True
                ) %}

                {% if company_address %}
                    {{ company_address.address_line1 or "" }},<br>
                    {{ company_address.city or "" }},
                    {{ company_address.state or "" }},
                    {{ company_address.pincode or "" }}<br>
                {% endif %}

                {% set company_details = frappe.db.get_value(
                    "Company",
                    doc.company,
                    ["website", "phone_no", "fax"],
                    as_dict=True
                ) %}
                TEL: {{ company_details.phone_no or "" }},<br>
                FAX: {{ company_details.fax or "" }}<br>
                
                {{ company_details.website or "" }}
            </td>
        </tr>
    </table>
    <div style="border-top: 2px solid #222; margin-top: 2px; padding: 0;"></div>
    <div style="border-top: 3px solid #222; margin: 4px 0 0 0; padding: 0;"></div>
</div>

    <table style="width:100%; margin-top:10px; font-size:12px;">
        <tr>
            <td>
                <strong>Reference Quotation:</strong> {{ doc.name }}
            </td>

            <td align="right">
                <strong>Date:</strong>
                {{ frappe.utils.formatdate(doc.transaction_date, "dd MMM yyyy") }}
            </td>
        </tr>
            
        <table style="width:100%; border-collapse:collapse; margin:8px 0; font-size:12px;">
    <!-- Address Headers -->
    <tr style="background:#d9d9d9;">
        <td colspan="2" style="border:1px solid #000; padding:3px;">
            <b>CUSTOMER BILL TO</b>
        </td>

    </tr>

    <tr>
        <td colspan="2" style="border:1px solid #000; padding:2px; vertical-align:top; line-height:1.25;">

            {% if doc.customer_address %}
                {% set bill = frappe.get_doc("Address", doc.customer_address) %}

                <b>{{ bill.address_title or doc.customer_name }}</b><br>

                {{ bill.address_line1 or "" }}<br>

                {% if bill.address_line2 %}
                    {{ bill.address_line2 }}<br>
                {% endif %}

                {{ bill.city or "" }}
                {% if bill.state %}, {{ bill.state }}{% endif %}
                {% if bill.pincode %} - {{ bill.pincode }}{% endif %}<br>

                {{ bill.country or "" }}

                {% if bill.phone %}
                    <br><b>Phone:</b> {{ bill.phone }}
                {% endif %}
            {% endif %}

        </td>

    </tr>

</table>
    </table>


    {# Check if all inspection tables are empty #}
    {% if not accepted_items and not repair_items and not rejected_items %}
    <div style="border: 1px solid #000; padding: 10px; text-align: center; font-weight: bold; margin: 20px 0;">
        No inspection records available.
    </div>
    {% endif %}

    {% if accepted_items %}
    <h3>Accepted Items</h3>

    <p>
        The following items have been accepted after inspection.
    </p>

    <table style="width:100%; border-collapse:collapse;">

        <thead>

            <tr style="background:#d9d9d9; font-weight:bold;">

                <th style="border:1px solid #000; padding:5px; text-align:center; color:black; font-weight:bold;">QUANTITY</th>

                <th style="border:1px solid #000; padding:5px; text-align:center; color:black; font-weight:bold;">ITEM CODE</th>

                <th style="border:1px solid #000; padding:5px; text-align:center; color:black; font-weight:bold;">ITEM NAME</th>

                <th style="border:1px solid #000; padding:5px; text-align:center; color:black; font-weight:bold;">IMAGE</th>

            </tr>

        </thead>

        <tbody>

            {% for row in accepted_items %}
        
            <tr>

                <td style="border:1px solid #000; padding:5px; text-align:center;">
                    {{ row.quantity }}
                </td>

                <td style="border:1px solid #000; padding:5px; text-align:center;">
                    {{ row.repair_item_code }}
                </td>

                <td style="border:1px solid #000; padding:5px; text-align:center;">
                    {{ row.item_name }}
                </td>

                <td style="border:1px solid #000; padding:5px; text-align:center;">

                    {% if row.image %}

                    <img src="{{ frappe.utils.get_url(row.image) }}"
                         style="width:60px; height:60px; object-fit:contain;">

                    {% endif %}

                </td>

            </tr>

            {% endfor %}

        </tbody>

    </table>

    <br><br>
    {% endif %}

    {% if repair_items %}
    <h3>Repair Items</h3>

    <p>
        The following items require repair before further processing.
    </p>

    <table style="width:100%; border-collapse:collapse;">

        <thead>

            <tr style="background:#d9d9d9; font-weight:bold;">

                <th style="border:1px solid #000; padding:5px; text-align:center; color:black; font-weight:bold;">QUANTITY</th>

                <th style="border:1px solid #000; padding:5px; text-align:center; color:black; font-weight:bold;">ITEM CODE</th>

                <th style="border:1px solid #000; padding:5px; text-align:center; color:black; font-weight:bold;">ACCEPTED QTY</th>

                <th style="border:1px solid #000; padding:5px; text-align:center; color:black; font-weight:bold;">IMAGE</th>

            </tr>

        </thead>

        <tbody>

            {% for row in repair_items %}

            <tr>

                <td style="border:1px solid #000; padding:5px; text-align:center;">
                    {{ row.quantity }}
                </td>
                
                <td style="border:1px solid #000; padding:5px; text-align:center;">
                    {{ row.repair_item_code }}
                </td>

                <td style="border:1px solid #000; padding:5px; text-align:center;">
                    {{ row.accepted_qty }}
                </td>

                <td style="border:1px solid #000; padding:5px; text-align:center;">

                    {% if row.image %}

                    <img src="{{ frappe.utils.get_url(row.image) }}"
                         style="width:60px; height:60px; object-fit:contain;">

                    {% endif %}

                </td>

            </tr>

            {% endfor %}

        </tbody>

    </table>

    <br><br>
    {% endif %}

    {% if doc.custom_rejected_qty %}
    <p>
        <b>Rejection Qty: </b><b style="color:red;">{{ doc.custom_rejected_qty or "" }}</b>
    </p>
    {% endif %}
    
    
    {% if doc.custom_rejected_reason %}
    <p>
        <b>Rejected Reason:- </b><b style="color:red;">{{ doc.custom_rejected_reason or "" }}</b>
    </p>
    {% endif %}
    
    {% if doc.custom_rejection_notes %}
    <p>
        <b>Rejection Notes:- </b><b style="color:red;">{{ doc.custom_rejection_notes or "" }}</b>
    </p>
    {% endif %}
    
    {% if doc.tc_name %}
    <br>

    <div>

        <strong>Terms & Conditions</strong>

        <div>

            {{ doc.terms or "" }}

        </div>

    </div>
    {% endif %}
</div>
